import math

def count_permutations(n: int, r: int) -> int:
    """
    Return the number of permutations of r items chosen from n items (nPr).
    """
    if n < 0 or r < 0:
        raise ValueError("n and r must be non-negative integers")
    if r > n:
        return 0
    return math.factorial(n) // math.factorial(n - r)
```

