def matrix_multiply(a, b):
    if not a or not a[0] or not b or not b[0]:
        return []
    m, n = len(a), len(a[0])
    if len(b) != n:
        raise ValueError("Incompatible dimensions")
    p = len(b[0])
    return [[sum(a[i][k] * b[k][j] for k in range(n)) for j in range(p)] for i in range(m)]
```

